const $=s=>document.querySelector(s);const content=$('#content'),sheet=$('#sheet'),toast=$('#toast');let screen='today',selectedFloor=null,state,selectedDate=localISODate(),selectedChecklistService='fixacao';
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
