function sessionEmployeeMinutes(session){const totals={};for(const seg of session.segments||[]){const start=timeMinutes(seg.start),end=timeMinutes(seg.end);if(start===null||end===null||end<start)continue;const events=[...(session.crewEvents||[])].filter(e=>{const t=timeMinutes(e.time);return t!==null&&t>start&&t<end}).sort((a,b)=>timeMinutes(a.time)-timeMinutes(b.time));let cursor=start,ids=crewAt(session,seg.start);const add=(until)=>{for(const id of ids)totals[id]=(totals[id]||0)+(until-cursor);cursor=until};for(const event of events){const t=timeMinutes(event.time);add(t);ids=event.employeeIds}add(end)}return totals}function employeeStats(id,daysBack=30){const cutoff=shiftDate(localISODate(),-(daysBack-1));let minutes=0,sessions=0,completed=0;for(const s of allSessions().filter(x=>x.state==='finished'&&x.date>=cutoff)){const byEmployee=sessionEmployeeMinutes(s),worked=Number(byEmployee[id]||0);if(!worked)continue;minutes+=worked;sessions++;if(s.result==='completed')completed++}return{hours:minutes/60,sessions,completed}}function plannedActualByService(daysBack=7){const cutoff=shiftDate(localISODate(),-(daysBack-1)),rows={};for(const [date,day] of Object.entries(state.days||{})){if(date<cutoff||date>localISODate())continue;for(const p of day.plans||[]){const r=rows[p.service]||(rows[p.service]={service:p.service,planned:0,executed:0,finished:0,completed:0,manHours:0});r.planned++;if((day.sessions||[]).some(s=>s.state==='finished'&&s.service===p.service&&Number(s.floor)===Number(p.floor)))r.executed++}for(const s of day.sessions||[]){if(s.state!=='finished')continue;const r=rows[s.service]||(rows[s.service]={service:s.service,planned:0,executed:0,finished:0,completed:0,manHours:0});r.finished++;r.manHours+=sessionManHours(s);if(s.result==='completed')r.completed++}}return Object.values(rows)}function completionDate(service,floor){return(state.history||[]).filter(h=>h.service===service&&Number(h.floor)===Number(floor)&&h.date).map(h=>h.date).sort().at(-1)||null}function scheduleHealth(service){let onTime=0,late=0,overdue=0,due=0;for(const f of state.floors||[]){const st=f.stages?.find(s=>s.service===service);if(!st?.targetDate||f.number<0)continue;due++;if(st.status==='completed'){const done=completionDate(service,f.number);if(done&&done<=st.targetDate)onTime++;else if(done)late++}else if(st.targetDate<localISODate())overdue++}return{onTime,late,overdue,due}}function serviceForecast(group){if(!group?.completed||!group.manHours)return null;const open=(state.floors||[]).filter(f=>f.number>=0).filter(f=>{const s=f.stages?.find(x=>x.service===group.service);return s&&s.status!=='completed'&&s.status!=='blocked'}).length,activeCrew=Math.max(1,state.employees.filter(e=>String(e.frontKey||'').startsWith(`${group.service}:`)).length),mhPerCompletion=group.manHours/group.completed;return{open,activeCrew,mhPerCompletion,days:open*mhPerCompletion/(activeCrew*8)}}function employeeChecks(selected=[]){const set=new Set(selected);return`<div class="crew-grid">${rdoPeople().map(e=>`<label class="crew-choice"><input type="checkbox" value="${e.id}" ${set.has(e.id)?'checked':''}><span>${esc(e.name)}</span></label>`).join('')}</div>`}
function sessionCard(s){const minutes=sessionMinutes(s),crew=(s.crewEvents?.[0]?.employeeIds||[]).map(employeeName),changes=(s.crewEvents||[]).slice(1),range=(s.segments||[]).map(x=>`${x.start}–${x.end||'...'}`).join(' · ');return`<div class="card session-card" data-session="${s.id}"><div class="row"><div><div class="title">${esc(SERVICES[s.service]?.[0]||s.service)} · ${floorLabel(Number(s.floor))}</div><div class="meta">${range||'Sem horário'} · ${minutes?`${formatMinutes(minutes)} produtivas`:'em curso'}</div><div class="meta">Equipe inicial: ${crew.map(esc).join(', ')||'não informada'}${s.corrected?' · Horários corrigidos':''}</div>${changes.map(e=>`<div class="meta">Equipe atualizada ${esc(e.time)} · ${e.employeeIds.map(employeeName).map(esc).join(', ')||'sem equipe'}</div>`).join('')}${s.result?`<div class="meta">Resultado físico: ${sessionResultLabel(s.result)}${s.note?` · ${esc(s.note)}`:''}</div>`:''}</div><span class="badge ${sessionTone(s.state)}">${sessionStateLabel(s.state)}</span></div><div class="session-actions">${s.state==='running'?'<button class="linkbtn session-pause">Pausar</button>':''}${s.state==='paused'?'<button class="linkbtn session-resume">Retomar</button>':''}${s.state!=='finished'?'<button class="btn session-finish">Concluir</button><button class="linkbtn session-crew">Atualizar equipe</button>':''}<button class="linkbtn session-edit">Editar horários</button><button class="linkbtn session-details">Detalhes</button></div></div>`}
