function openNewSession(prefill={}){const service=prefill.service||'afaq',floor=Number(prefill.floor??11),linked=linkedCrewIds(service,floor),preset=linked.length?linked:(prefill.employeeIds||[]),start=prefill.start||state.settings.defaultWorkStart||'07:30';(sheet.innerHTML=`<div class="sheet"><div class="sheet-head"><div><h2>Novo apontamento</h2><div class="meta">Registre o executado sem alterar automaticamente o avanço físico.</div></div><button class="close">×</button></div><div class="form"><label>Serviço<select id="sservice">${Object.entries(SERVICES).map(([k,v])=>`<option value="${k}" ${k===service?'selected':''}>${v[0]}</option>`).join('')}</select></label><label>Pavimento<select id="sfloor">${state.floors.filter(f=>f.number>=0).map(f=>`<option value="${f.number}" ${f.number===floor?'selected':''}>${floorLabel(f.number)}</option>`).join('')}</select></label><label>Início<div class="time-inline"><input id="sstart" type="time" value="${start}"><button type="button" id="startNow" class="linkbtn">Agora</button></div></label><div><div class="form-label">Funcionários</div><div id="sessionCrew">${employeeChecks(preset)}</div></div></div><button class="btn" id="createSession">Criar apontamento</button></div>`, document.dispatchEvent(new CustomEvent('field:sheet-rendered')));sheet.showModal();sheet.querySelector('.close').addEventListener('click',()=>sheet.close());$('#startNow').addEventListener('click',()=>{$('#sstart').value=nowTime()});const syncCrew=()=>{const ids=linkedCrewIds($('#sservice').value,Number($('#sfloor').value));$('#sessionCrew').innerHTML=employeeChecks(ids)};$('#sservice').addEventListener('change',syncCrew);$('#sfloor').addEventListener('change',syncCrew);$('#createSession').addEventListener('click',async()=>{const ids=[...sheet.querySelectorAll('#sessionCrew input:checked')].map(i=>i.value),startValue=$('#sstart').value;if(!ids.length)return show('Selecione ao menos 1 funcionário.');if(timeMinutes(startValue)===null)return show('Informe um horário de início válido.');const d=getDay(selectedDate,true),session={id:crypto.randomUUID(),date:selectedDate,service:$('#sservice').value,floor:Number($('#sfloor').value),state:'running',segments:[{start:startValue,end:null}],crewEvents:[{time:startValue,employeeIds:ids}],result:null,note:'',corrected:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};d.sessions.push(session);await save();sheet.close();renderDay();show('Apontamento iniciado.')})}
async function pauseSession(id){const d=getDay(selectedDate,true),s=getSession(d,id),open=[...(s?.segments||[])].reverse().find(x=>!x.end);if(!s||s.state!=='running'||!open)return;open.end=safeActionTime(s);s.state='paused';s.updatedAt=new Date().toISOString();await save();renderDay();show('Apontamento pausado.')}
