$('#openRdoPhotos')?.addEventListener('click',()=>void openRdoPhotos());
$('#openRdoOccurrences')?.addEventListener('click',openRdoOccurrences);
$('#goRdoPending')?.addEventListener('click',()=>document.querySelector('#rdoChecklist')?.scrollIntoView({block:'start',behavior:'smooth'}));
