function renderFloors(){(content.innerHTML=`<div class="section-head"><div><h2>Pavimentos</h2><p>Mapa da obra: ${floorLabel(Number(state.project?.startFloor??0))} ao ${floorLabel(Number(state.project?.targetFloor??1))}.</p></div></div><div class="grid">${state.floors.map(f=>`<div class="card floor" data-floor="${f.number}"><div class="row"><strong>${floorLabel(f.number)}</strong><span>${f.number<0?'Não liberado':`${progress(f)}%`}</span></div><div class="bar"><span style="width:${f.number<0?0:progress(f)}%"></span></div></div>`).join('')}</div>`, document.dispatchEvent(new CustomEvent('field:rendered')));document.querySelectorAll('.floor').forEach(el=>el.addEventListener('click',()=>{selectedFloor=Number(el.dataset.floor);renderFloor()}))}
