function renderIssues(){const open=state.issues.filter(i=>i.status==='open');(content.innerHTML=`<div class="section-head"><div><h2>Pendências</h2><p>Qualidade e bloqueios.</p></div><button class="linkbtn" id="newIssue">+ Nova</button></div>${open.map(i=>`<div class="card"><div class="row"><strong>${esc(i.title)}</strong><span class="badge ${i.type==='blocked'?'blocked':'progress'}">${i.type==='blocked'?'Bloqueio':'Pendência'}</span></div><div class="meta">${floorLabel(i.floor)} · ${SERVICES[i.service][0]}${i.external?' · responsabilidade externa':''}</div><p>${esc(i.reason||'')}</p></div>`).join('')||'<div class="empty">Nenhuma pendência aberta.</div>'}`, document.dispatchEvent(new CustomEvent('field:rendered')));$('#newIssue').addEventListener('click',openIssue)}
