async function saveChecklistModel(){const rows=[...document.querySelectorAll('.check-admin-row')],items=rows.map((r,i)=>({id:r.dataset.id.startsWith('tmp-')?`${selectedChecklistService}-${crypto.randomUUID()}`:r.dataset.id||`${selectedChecklistService}-${i}`,label:r.querySelector('.check-label-input').value.trim(),required:r.querySelector('.check-required').checked})).filter(i=>i.label);state.checklistTemplates[selectedChecklistService]=items;state.floors.forEach(f=>{const st=f.stages.find(s=>s.service===selectedChecklistService);if(!st||st.status==='completed')return;const old=st.checklist||[];st.checklist=items.map(item=>{const prev=old.find(x=>x.id===item.id)||old.find(x=>x.label===item.label);return{...item,checked:prev?.checked||false}})});await save();renderSettings();show('Modelo salvo e aplicado às etapas abertas.')}
function days(baseCrew,baseDays,actual,eff=.7){const effective=actual<=baseCrew?actual:baseCrew+(actual-baseCrew)*eff;return baseDays*baseCrew/effective}
function renderMore(){const productivity=productivityByService(),compare=plannedActualByService(),today=getDay(localISODate(),false),todayPlanned=(today.plans||[]).length,todayFinished=(today.sessions||[]).filter(s=>s.state==='finished').length,weekPlanned=compare.reduce((n,r)=>n+r.planned,0),weekExecuted=compare.reduce((n,r)=>n+r.executed,0),weekPct=weekPlanned?Math.round(weekExecuted/weekPlanned*100):0;(content.innerHTML=`<div class="section-head"><div><h2>Planejamento</h2><p>Previsto × realizado, produtividade e tendência a partir dos apontamentos reais.</p></div></div><div class="metrics planning-top"><div class="metric"><span>Planejado hoje</span><strong>${todayPlanned}</strong></div><div class="metric"><span>Executado hoje</span><strong>${todayFinished}</strong></div><div class="metric"><span>Aderência 7 dias</span><strong>${weekPlanned?`${weekPct}%`:'—'}</strong></div><div class="metric"><span>Faltas médias/semana</span><strong>${Number(state.settings.averageWeeklyAbsences||0)}</strong></div></div><section class="section"><div class="section-head"><div><h2>Previsto × realizado · 7 dias</h2><p>Um planejamento conta como realizado quando existe sessão concluída da mesma etapa e pavimento.</p></div></div>${compare.length?compare.map(r=>{const pct=r.planned?Math.round(r.executed/r.planned*100):null,tone=pct===null?'':pct>=90?'completed':pct>=70?'released':'overdue';return`<div class="card comparison-card"><div class="row"><div><strong>${esc(SERVICES[r.service]?.[0]||r.service)}</strong><div class="meta">${r.planned} planejado(s) · ${r.executed} executado(s) · ${r.completed} conclusão(ões)</div></div><span class="badge ${tone}">${pct===null?'Sem meta':`${pct}%`}</span></div><div class="comparison-bar"><i style="width:${Math.min(100,pct||0)}%"></i></div><div class="meta">${r.manHours.toFixed(1)} HH no período</div></div>`}).join(''):'<div class="empty card">Cadastre planejamentos e finalize sessões para formar a comparação.</div>'}</section><section class="section"><div class="section-head"><div><h2>Produtividade real</h2><p>Histórico acumulado das sessões encerradas.</p></div></div>${productivity.length?productivity.map(g=>{const health=scheduleHealth(g.service),forecast=serviceForecast(g);return`<div class="card productivity-card"><div class="row"><strong>${SERVICES[g.service]?.[0]||g.service}</strong><span class="badge completed">${g.sessions} sessão(ões)</span></div><div class="metrics compact-metrics"><div class="metric"><span>Horas produtivas</span><strong>${(g.minutes/60).toFixed(1)}h</strong></div><div class="metric"><span>Homem-hora</span><strong>${g.manHours.toFixed(1)}</strong></div></div><div class="meta">Conclusões físicas: ${g.completed}${g.completed?` · ${g.manHours/g.completed>=0?(g.manHours/g.completed).toFixed(1):'—'} HH/conclusão`:''}</div><div class="productivity-signals"><span>${health.overdue} meta(s) vencida(s)</span><span>${health.onTime} no prazo</span><span>${health.late} concluída(s) após meta</span></div>${forecast?`<div class="forecast"><b>Projeção operacional</b><span>${forecast.open} etapa(s) abertas · equipe atual ${forecast.activeCrew} · ~${forecast.days.toFixed(1)} dia(s) úteis no ritmo histórico</span></div>`:''}</div>`}).join(''):'<div class="empty card">Ainda não há sessões concluídas suficientes para produtividade real.</div>'}</section><section class="section card"><strong>Simulador de equipe · AF/AQ</strong><div class="meta">Base teórica atual: 4 pessoas · 5 dias/pavimento. O simulador não altera o planejamento salvo.</div><input class="range" id="crew" type="range" min="4" max="8" value="6"><div class="metrics" style="margin-top:12px"><div class="metric"><span>Equipe</span><strong id="crewVal">6</strong></div><div class="metric"><span>Ciclo estimado</span><strong id="cycle"></strong></div></div></section><button type="button" class="quick-action single-action" data-screen="settings"><strong>Configurações</strong><span>Horário padrão e checklists das etapas</span></button><section class="section card"><strong>Instalar no iPhone</strong><p class="meta">Abra no Safari → Compartilhar → Adicionar à Tela de Início. O app abre em modo standalone e guarda os dados deste aparelho.</p></section>`, document.dispatchEvent(new CustomEvent('field:rendered')));const r=$('#crew'),update=()=>{$('#crewVal').textContent=r.value;$('#cycle').textContent=`${days(4,5,Number(r.value)).toFixed(2)} d`};r?.addEventListener('input',update);if(r)update()}
function bridgeLabel(entity){return({frentes_obra:'Etapa',tarefas_obra:'Tarefa',rdos:'RDO',cronograma_etapas:'Cronograma'})[entity]||entity}
function bridgeTitle(item){const p=item?.payload||{};if(item.entity==='frentes_obra')return p.nome||`Etapa #${item.localId}`;if(item.entity==='tarefas_obra')return p.titulo||`Tarefa #${item.localId}`;if(item.entity==='rdos')return `RDO ${p.data||`#${item.localId}`}`;if(item.entity==='cronograma_etapas')return p.nome||`Programação #${item.localId}`;return`#${item.localId}`}
function bridgeMeta(item){const p=item?.payload||{};if(item.entity==='tarefas_obra')return`${p.status||'aberta'}${p.prazo?` · prazo ${dateBR(p.prazo)}`:''}`;if(item.entity==='frentes_obra')return String(p.status||'ativa');if(item.entity==='rdos')return String(p.status||'rascunho');if(item.entity==='cronograma_etapas')return`${p.status||'pendente'} · ${Number(p.percentual_realizado||0)}%`;return''}
function bridgeAction(item){const p=item?.payload||{};if(item.entity==='tarefas_obra')return p.status==='concluida'?['Reabrir',{status:'aberta',concluido_em:null}]:['Concluir',{status:'concluida',concluido_em:new Date().toISOString()}];if(item.entity==='frentes_obra')return p.status==='concluida'?['Reabrir',{status:'ativa'}]:['Concluir',{status:'concluida'}];if(item.entity==='rdos')return p.status==='finalizado'?['Reabrir',{status:'rascunho'}]:['Finalizar',{status:'finalizado'}];if(item.entity==='cronograma_etapas'){const n=Math.min(100,Number(p.percentual_realizado||0)+10);return[`Avançar para ${n}%`,{percentual_realizado:n,status:n>=100?'concluido':p.status||'em_andamento'}]}return null}
function conflictFieldLabel(key){return({status:'Status',titulo:'Título',nome:'Nome',responsavel:'Responsável',prazo:'Prazo',prioridade:'Prioridade',descricao:'Descrição',observacoes:'Observações',percentual_realizado:'Progresso',clima:'Clima',atividades:'Atividades'}[key]||key)}
function conflictValue(value){if(value===null||value===undefined||value==='')return'—';if(Array.isArray(value))return value.map(conflictValue).join(', ');if(typeof value==='object')return JSON.stringify(value);return String(value)}
function conflictCurrentItem(conflict,items){return items.find(item=>item.entity===conflict.entity&&Number(item.localId)===Number(conflict.localId)&&String(item.sourceDeviceId||'')===String(conflict.sourceDeviceId||''))}
function conflictDiff(conflict,items){const current=conflictCurrentItem(conflict,items),obra=current?.payload||{},computer=conflict?.change?.payload||{},keys=Array.from(new Set([...Object.keys(obra),...Object.keys(computer)])).filter(key=>!['deleted','updatedAt','lastAppliedChangeId','appliedChangeIds'].includes(key)),changed=keys.filter(key=>JSON.stringify(obra[key]??null)!==JSON.stringify(computer[key]??null)).slice(0,6);if(!changed.length)return'<div class="meta">As duas versões foram alteradas em momentos diferentes. Escolha qual deve prevalecer.</div>';return`<div class="conflict-diff"><div class="conflict-diff-head"><span>Campo</span><span>Obra360</span><span>Computador</span></div>${changed.map(key=>`<div class="conflict-diff-row"><strong>${esc(conflictFieldLabel(key))}</strong><span>${esc(conflictValue(obra[key]))}</span><span>${esc(conflictValue(computer[key]))}</span></div>`).join('')}</div>`}
async function editBridge(item,patch){if(!window.mobileBridgeUpdate)return show('Seu perfil não pode alterar este item.');try{await window.mobileBridgeUpdate({entity:item.entity,localId:item.localId,sourceDeviceId:item.sourceDeviceId,patch});state=await window.multiuserReloadProject();renderObra360();show('Alteração salva na obra. O Desktop receberá automaticamente quando estiver conectado.')}catch(e){show(e?.message||'Não foi possível atualizar.')}}
function bridgeDomainSection(title,description,entity,items){const rows=items.filter(item=>item.entity===entity);return`<section class="section"><div class="section-head"><div><h2>${title}</h2><p>${description}</p></div></div>${rows.map(item=>{const action=bridgeAction(item);return`<div class="card bridge-card"><div class="row"><div><span class="badge released">${bridgeLabel(item.entity)}</span><strong class="bridge-title">${esc(bridgeTitle(item))}</strong><div class="meta">${esc(bridgeMeta(item))} · Origem: computador</div></div>${action?`<button class="linkbtn bridge-action" data-key="${esc(`${item.entity}:${item.localId}:${item.sourceDeviceId}`)}">${esc(action[0])}</button>`:''}</div></div>`}).join('')||'<div class="empty card">Nenhum registro nesta área.</div>'}</section>`}
function renderObra360(){const bridge=state.desktopBridge||{},items=['fronts','tasks','rdos','schedule'].flatMap(k=>Array.isArray(bridge[k])?bridge[k]:[]).filter(x=>!x.deleted),conflicts=window.mobileSyncConflicts||[],today=getDay(localISODate(),false),active=(today.assignments||[]).filter(isActiveAssignment);(content.innerHTML=`<section class="hero"><small>Operação da obra</small><div class="date">Obra</div><div class="stats"><div class="stat"><strong>${active.length}</strong><span>etapas hoje</span></div><div class="stat"><strong>${items.length}</strong><span>registros integrados</span></div><div class="stat"><strong>${conflicts.length}</strong><span>conflitos</span></div></div></section><div class="quick-actions"><button class="quick-action" data-screen="floors"><strong>Pavimentos</strong><span>Etapas e checklists</span></button><button class="quick-action" data-screen="issues"><strong>Pendências</strong><span>Qualidade e bloqueios</span></button><button class="quick-action" data-screen="more"><strong>Planejamento</strong><span>Produtividade e previsão</span></button><button class="quick-action" data-screen="settings"><strong>Configurações</strong><span>Checklists e horários</span></button></div>${bridgeDomainSection('Tarefas','Tarefas da obra disponíveis em qualquer dispositivo.','tarefas_obra',items)}${bridgeDomainSection('Etapas','Etapas de serviço compartilhadas da obra.','frentes_obra',items)}${bridgeDomainSection('RDOs','Registros diários integrados da obra.','rdos',items)}${bridgeDomainSection('Planejamento','Etapas e avanço físico compartilhados.','cronograma_etapas',items)}${conflicts.length?`<section class="section"><div class="section-head"><div><h2>Alterações para revisar</h2><p>O mesmo registro foi alterado no computador e no Obra360. Nada será substituído sem sua escolha.</p></div></div>${conflicts.map(c=>{const item=items.find(x=>x.entity===c.entity&&Number(x.localId)===Number(c.localId));return`<div class="card conflict-card"><strong>${esc(item?bridgeTitle(item):bridgeLabel(c.entity))}</strong><div class="meta">Compare a versão usada no Obra360 com a alteração feita no computador.</div>${window.mobileResolveConflict?`<div class="conflict-actions"><button class="linkbtn mobile-conflict" data-id="${c.id}" data-resolution="keep_mobile">Manter versão do Obra360</button><button class="btn mobile-conflict" data-id="${c.id}" data-resolution="accept_desktop">Usar versão do computador</button></div>`:''}</div>`}).join('')}</section>`:''}`, document.dispatchEvent(new CustomEvent('field:rendered')));document.querySelectorAll('.bridge-action').forEach(b=>b.addEventListener('click',()=>{const item=items.find(x=>`${x.entity}:${x.localId}:${x.sourceDeviceId}`===b.dataset.key),action=item&&bridgeAction(item);if(item&&action)void editBridge(item,action[1])}));document.querySelectorAll('.mobile-conflict').forEach(b=>b.addEventListener('click',async()=>{try{await window.mobileResolveConflict(b.dataset.id,b.dataset.resolution);state=await window.multiuserReloadProject();renderObra360();show('Versão escolhida. A obra será sincronizada automaticamente.')}catch(e){show(e?.message||'Não foi possível resolver.')}}))}
function renderManagement(){const summary=window.mobileReadOnlySummary||{},html=window.mobileManagementHtml?window.mobileManagementHtml(summary,window.multiuserContext?.bootstrap?.access):'<div class="empty card premium-empty">Resumo indisponível.</div>',freshness=window.mobileSummaryFreshness?.(summary.generatedAt),published=freshness?.label||'Sem data de publicação do Desktop';(content.innerHTML=`<section class="hero field-hero management-hero"><a class="hero-back" href="./sistema.html#portal" aria-label="Voltar ao painel geral">←</a><div class="management-hero-copy"><span class="hero-main-icon" aria-hidden="true"><i></i><i></i><i></i></span><div><div class="management-title">Gestão</div><p>Visão administrativa da operação</p></div></div></section><section class="section management-section"><div class="section-head"><div><h2>Indicadores e KPI's</h2><p>${esc(published)}</p></div></div><div class="management-grid">${html}</div></section>`, document.dispatchEvent(new CustomEvent('field:rendered')))}
function render(){content.classList.add('field-screen-staging');nav();if(screen==='today')renderDay();if(screen==='obra360')renderObra360();if(screen==='floors')selectedFloor!==null?renderFloor():renderFloors();if(screen==='team')renderTeam();if(screen==='issues')renderIssues();if(screen==='more')renderMore();if(screen==='settings')renderSettings();if(screen==='management')renderManagement()}
document.addEventListener('click',e=>{const action=e.target.closest('[data-field-action]');if(action){document.getElementById(action.dataset.fieldAction)?.click();return}const b=e.target.closest('[data-screen]');if(!b)return;screen=b.dataset.screen;selectedFloor=null;render()});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{}));let optionalRefreshScheduled=false;
window.addEventListener('field:aux-data-ready',event=>{
  const resource=event.detail?.resource;
  if(!((resource==='receipts'&&screen==='today')||(resource==='summary'&&screen==='management')||(resource==='conflicts'&&screen==='obra360')))return;
  if(optionalRefreshScheduled)return;
  optionalRefreshScheduled=true;
  requestAnimationFrame(()=>{
    optionalRefreshScheduled=false;
    // Never discard an edit in progress when an optional request finishes.
    const focused=document.activeElement;
    if(focused&&content.contains(focused)&&/^(INPUT|TEXTAREA|SELECT)$/.test(focused.tagName))return;
    if(screen==='today')renderDay();
    else if(screen==='management')renderManagement();
    else if(screen==='obra360')renderObra360();
  });
});
state=await load();render();
